CREATE TYPE "UserRole" AS ENUM ('PARENT', 'CHILD');
CREATE TYPE "PurseType" AS ENUM ('EXPENSES', 'SAVINGS', 'DONATION');
CREATE TYPE "LedgerKind" AS ENUM ('INCOME_ALLOCATION', 'EXPENSE', 'CASH_REQUEST_PAID', 'INTEREST_CREDIT', 'SAVINGS_GOAL_REDEEMED', 'DONATION_COMPLETED', 'REVERSAL');
CREATE TYPE "RequestStatus" AS ENUM ('PENDING', 'APPROVED', 'REJECTED', 'PAID');
CREATE TABLE "Family" ("id" UUID NOT NULL, "name" TEXT NOT NULL, "timezone" TEXT NOT NULL DEFAULT 'Asia/Jerusalem', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Family_pkey" PRIMARY KEY ("id"));
CREATE TABLE "User" ("id" UUID NOT NULL, "familyId" UUID NOT NULL, "email" TEXT NOT NULL, "passwordHash" TEXT NOT NULL, "role" "UserRole" NOT NULL DEFAULT 'PARENT', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "User_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Child" ("id" UUID NOT NULL, "familyId" UUID NOT NULL, "name" TEXT NOT NULL, "birthYear" INTEGER, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Child_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Purse" ("id" UUID NOT NULL, "childId" UUID NOT NULL, "type" "PurseType" NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Purse_pkey" PRIMARY KEY ("id"));
CREATE TABLE "LedgerEntry" ("id" UUID NOT NULL, "familyId" UUID NOT NULL, "purseId" UUID NOT NULL, "kind" "LedgerKind" NOT NULL, "amountAgorot" INTEGER NOT NULL, "idempotencyKey" TEXT NOT NULL, "note" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "LedgerEntry_pkey" PRIMARY KEY ("id"));
CREATE TABLE "AllocationPolicy" ("id" UUID NOT NULL, "familyId" UUID NOT NULL, "expensesBps" INTEGER NOT NULL, "savingsBps" INTEGER NOT NULL, "donationBps" INTEGER NOT NULL, "effectiveAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "AllocationPolicy_pkey" PRIMARY KEY ("id"));
CREATE TABLE "InterestPolicy" ("id" UUID NOT NULL, "familyId" UUID NOT NULL, "annualBps" INTEGER NOT NULL DEFAULT 0, "effectiveAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "InterestPolicy_pkey" PRIMARY KEY ("id"));
CREATE TABLE "SavingsGoal" ("id" UUID NOT NULL, "childId" UUID NOT NULL, "title" TEXT NOT NULL, "targetAgorot" INTEGER NOT NULL, "active" BOOLEAN NOT NULL DEFAULT true, "achievedAt" TIMESTAMP(3), "redeemedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "SavingsGoal_pkey" PRIMARY KEY ("id"));
CREATE TABLE "CashRequest" ("id" UUID NOT NULL, "childId" UUID NOT NULL, "amountAgorot" INTEGER NOT NULL, "reason" TEXT, "status" "RequestStatus" NOT NULL DEFAULT 'PENDING', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "CashRequest_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "User_email_key" ON "User"("email");
CREATE UNIQUE INDEX "Purse_childId_type_key" ON "Purse"("childId", "type");
CREATE UNIQUE INDEX "LedgerEntry_familyId_idempotencyKey_key" ON "LedgerEntry"("familyId", "idempotencyKey");
CREATE INDEX "LedgerEntry_purseId_createdAt_idx" ON "LedgerEntry"("purseId", "createdAt");
CREATE INDEX "LedgerEntry_familyId_createdAt_idx" ON "LedgerEntry"("familyId", "createdAt");
CREATE UNIQUE INDEX "AllocationPolicy_familyId_key" ON "AllocationPolicy"("familyId");
CREATE UNIQUE INDEX "InterestPolicy_familyId_key" ON "InterestPolicy"("familyId");
CREATE INDEX "SavingsGoal_childId_active_idx" ON "SavingsGoal"("childId", "active");
CREATE INDEX "CashRequest_childId_status_createdAt_idx" ON "CashRequest"("childId", "status", "createdAt");
ALTER TABLE "User" ADD CONSTRAINT "User_familyId_fkey" FOREIGN KEY ("familyId") REFERENCES "Family"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Child" ADD CONSTRAINT "Child_familyId_fkey" FOREIGN KEY ("familyId") REFERENCES "Family"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Purse" ADD CONSTRAINT "Purse_childId_fkey" FOREIGN KEY ("childId") REFERENCES "Child"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "LedgerEntry" ADD CONSTRAINT "LedgerEntry_purseId_fkey" FOREIGN KEY ("purseId") REFERENCES "Purse"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "AllocationPolicy" ADD CONSTRAINT "AllocationPolicy_familyId_fkey" FOREIGN KEY ("familyId") REFERENCES "Family"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "InterestPolicy" ADD CONSTRAINT "InterestPolicy_familyId_fkey" FOREIGN KEY ("familyId") REFERENCES "Family"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "SavingsGoal" ADD CONSTRAINT "SavingsGoal_childId_fkey" FOREIGN KEY ("childId") REFERENCES "Child"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "CashRequest" ADD CONSTRAINT "CashRequest_childId_fkey" FOREIGN KEY ("childId") REFERENCES "Child"("id") ON DELETE CASCADE ON UPDATE CASCADE;
CREATE FUNCTION prevent_ledger_mutation() RETURNS trigger AS $$ BEGIN RAISE EXCEPTION 'Ledger entries are append-only'; END; $$ LANGUAGE plpgsql;
CREATE TRIGGER "LedgerEntry_no_update" BEFORE UPDATE OR DELETE ON "LedgerEntry" FOR EACH ROW EXECUTE FUNCTION prevent_ledger_mutation();
